import base64
import json
import os
from typing import Any, Dict, Optional, Union

import boto3
from botocore.client import BaseClient
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


BytesLike = Union[bytes, bytearray, memoryview]


class KmsEnvelopeEncryption:
    def __init__(
        self,
        kms_key_id: str,
        region_name: Optional[str] = None,
        kms_client: Optional[BaseClient] = None,
        encryption_context: Optional[Dict[str, str]] = None,
    ) -> None:
        self.kms_key_id = kms_key_id
        self.encryption_context = encryption_context or {}
        self.kms = kms_client or boto3.client(
            "kms",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
        )

    @staticmethod
    def _to_bytes(data: Union[str, BytesLike]) -> bytes:
        if isinstance(data, str):
            return data.encode("utf-8")
        return bytes(data)

    @staticmethod
    def _b64e(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")

    @staticmethod
    def _b64d(data: str) -> bytes:
        return base64.b64decode(data.encode("ascii"))

    def encrypt(
        self,
        plaintext: Union[str, BytesLike],
        aad: Optional[Union[str, BytesLike]] = None,
    ) -> Dict[str, Any]:
        plaintext_bytes = self._to_bytes(plaintext)
        aad_bytes = self._to_bytes(aad) if aad is not None else None

        response = self.kms.generate_data_key(
            KeyId=self.kms_key_id,
            KeySpec="AES_256",
            EncryptionContext=self.encryption_context or None,
        )

        plaintext_data_key = response["Plaintext"]
        encrypted_data_key = response["CiphertextBlob"]

        try:
            aesgcm = AESGCM(plaintext_data_key)
            nonce = os.urandom(12)
            ciphertext_with_tag = aesgcm.encrypt(nonce, plaintext_bytes, aad_bytes)
        finally:
            plaintext_data_key = b"\x00" * len(plaintext_data_key)

        return {
            "provider": "aws-kms",
            "kms_key_id": self.kms_key_id,
            "algorithm": "AES-256-GCM",
            "encrypted_data_key": self._b64e(encrypted_data_key),
            "nonce": self._b64e(nonce),
            "ciphertext": self._b64e(ciphertext_with_tag),
            "encryption_context": self.encryption_context,
            "aad": self._b64e(aad_bytes) if aad_bytes is not None else None,
        }

    def decrypt(
        self,
        envelope: Dict[str, Any],
        aad: Optional[Union[str, BytesLike]] = None,
    ) -> bytes:
        encrypted_data_key = self._b64d(envelope["encrypted_data_key"])
        nonce = self._b64d(envelope["nonce"])
        ciphertext = self._b64d(envelope["ciphertext"])

        envelope_context = envelope.get("encryption_context") or {}
        aad_bytes = self._to_bytes(aad) if aad is not None else None

        if aad_bytes is None and envelope.get("aad") is not None:
            aad_bytes = self._b64d(envelope["aad"])

        response = self.kms.decrypt(
            CiphertextBlob=encrypted_data_key,
            EncryptionContext=envelope_context or None,
        )
        plaintext_data_key = response["Plaintext"]

        try:
            aesgcm = AESGCM(plaintext_data_key)
            return aesgcm.decrypt(nonce, ciphertext, aad_bytes)
        finally:
            plaintext_data_key = b"\x00" * len(plaintext_data_key)

    def encrypt_to_json(
        self,
        plaintext: Union[str, BytesLike],
        aad: Optional[Union[str, BytesLike]] = None,
    ) -> str:
        return json.dumps(self.encrypt(plaintext, aad), separators=(",", ":"))

    def decrypt_from_json(
        self,
        envelope_json: str,
        aad: Optional[Union[str, BytesLike]] = None,
    ) -> bytes:
        return self.decrypt(json.loads(envelope_json), aad)
